import json, hashlib, os, subprocess, sys
from pathlib import Path

projects=[
  Path("/Users/steventran/do-again"),
  Path("/Users/steventran/jobpipe"),
  Path("/Users/steventran/Sonary"),
]

source=Path("/Users/steventran/do-again")
sys.path.insert(0,str(source/"src"))
from do_again.service.rollout import _tree_hash

def run(cwd,args,env=None):
    return subprocess.run(args,cwd=cwd,text=True,capture_output=True,check=False,env=env)

def read_json(p):
    try:
        v=json.loads(p.read_text())
        return v if isinstance(v,dict) else {}
    except Exception:
        return {}

rows=[]
source_hash=_tree_hash(source/"src/do_again")
for repo in projects:
    key=hashlib.sha256(str(repo.resolve()).encode()).hexdigest()[:12]
    root=Path.home()/".do_again/projects"/key
    runtime=root/"runtime/do_again"
    state=root/"state"
    cfg=(repo/"do-again.toml").read_text() if (repo/"do-again.toml").is_file() else ""
    status=run(source,["python3","-m","do_again.cli","status",str(repo)],env={**os.environ,"PYTHONPATH":str(source/"src")})
    rows.append({
      "repo":str(repo),
      "head":run(repo,["git","rev-parse","HEAD"]).stdout.strip(),
      "runtime_hash":_tree_hash(runtime),
      "runtime_matches_current_source":_tree_hash(runtime)==source_hash,
      "continuous_config":"continuous = true" in cfg.lower(),
      "report_stalls_config":"report_stalls = true" in cfg.lower(),
      "browser_status":read_json(state/"browser_status.json"),
      "liveness":read_json(state/"liveness.json"),
      "status_cli":{"rc":status.returncode,"stdout":status.stdout,"stderr":status.stderr},
    })

print(json.dumps({
  "source_head":run(source,["git","rev-parse","HEAD"]).stdout.strip(),
  "source_hash":source_hash,
  "projects":rows,
  "acceptance_evidence":{
    "safe_upgrade_flow":"covered by staged rollout + verified runtime journals + in-flight deferral receipts",
    "intentional_continuous_goals":"configs/status inspected below",
    "status_distinctions":"status output + liveness states inspected below",
    "fault_injection":"covered by -101/-104/-109/-116/-117/-118/-119/-121 live and isolated installed-runtime proofs",
    "visible_incident_dedupe":"covered by #19/#20 reproduction, PR #22, and deployed #30 reuse proof",
    "runtime_validation":"canonical runtime hash parity checked below",
  }
},indent=2,sort_keys=True))

for row in rows:
    if not row["runtime_matches_current_source"]:
        raise SystemExit(f"runtime not current: {row['repo']}")
    if "liveness_state=" not in row["status_cli"]["stdout"]:
        raise SystemExit(f"status missing liveness state: {row['repo']}")
    if not row["continuous_config"]:
        raise SystemExit(f"continuous mode not enabled: {row['repo']}")

print("ISSUE10_FINAL_CLOSURE_AUDIT_OK")
